CREATE TABLE roles (id BIGINT IDENTITY PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE, description VARCHAR(255), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE users (id BIGINT IDENTITY PRIMARY KEY, role_id BIGINT NOT NULL, full_name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, avatar_url VARCHAR(500), gender VARCHAR(20), date_of_birth DATE, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', email_verified BIT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, last_login_at DATETIME2, CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(id), CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE','LOCKED','INACTIVE')));
CREATE TABLE categories (id BIGINT IDENTITY PRIMARY KEY, parent_id BIGINT, name VARCHAR(150) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, description VARCHAR(1000), image_url VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, CONSTRAINT fk_categories_parent FOREIGN KEY (parent_id) REFERENCES categories(id));
CREATE TABLE brands (id BIGINT IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(150) NOT NULL UNIQUE, logo_url VARCHAR(500), description VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2);
CREATE TABLE products (id BIGINT IDENTITY PRIMARY KEY, category_id BIGINT NOT NULL, brand_id BIGINT NOT NULL, name VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, description NVARCHAR(MAX), material VARCHAR(255), base_price DECIMAL(19,2) NOT NULL, sale_price DECIMAL(19,2), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', featured BIT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id), CONSTRAINT fk_products_brand FOREIGN KEY (brand_id) REFERENCES brands(id), CONSTRAINT ck_products_prices CHECK (base_price >= 0 AND (sale_price IS NULL OR sale_price >= 0)));
CREATE TABLE product_images (id BIGINT IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, image_url VARCHAR(500) NOT NULL, is_primary BIT NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE sizes (id BIGINT IDENTITY PRIMARY KEY, name VARCHAR(20) NOT NULL UNIQUE, description VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE colors (id BIGINT IDENTITY PRIMARY KEY, name VARCHAR(50) NOT NULL, color_code VARCHAR(20), status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE product_variants (id BIGINT IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, size_id BIGINT NOT NULL, color_id BIGINT NOT NULL, sku VARCHAR(80) NOT NULL UNIQUE, price DECIMAL(19,2) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (product_id) REFERENCES products(id), FOREIGN KEY (size_id) REFERENCES sizes(id), FOREIGN KEY (color_id) REFERENCES colors(id), CONSTRAINT uk_variants_combination UNIQUE(product_id,size_id,color_id), CONSTRAINT ck_variants_price CHECK (price >= 0));
CREATE TABLE inventories (id BIGINT IDENTITY PRIMARY KEY, variant_id BIGINT NOT NULL UNIQUE, quantity INT NOT NULL DEFAULT 0, reserved_quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (variant_id) REFERENCES product_variants(id), CHECK(quantity >= 0 AND reserved_quantity >= 0 AND reorder_level >= 0));
CREATE TABLE inventory_transactions (id BIGINT IDENTITY PRIMARY KEY, variant_id BIGINT NOT NULL, transaction_type VARCHAR(20) NOT NULL, quantity INT NOT NULL, reference_type VARCHAR(50), reference_id BIGINT, note VARCHAR(1000), created_by BIGINT, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (variant_id) REFERENCES product_variants(id), FOREIGN KEY (created_by) REFERENCES users(id));
CREATE TABLE user_addresses (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, receiver_name VARCHAR(150) NOT NULL, receiver_phone VARCHAR(30) NOT NULL, province VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, ward VARCHAR(100) NOT NULL, address_detail VARCHAR(255) NOT NULL, is_default BIT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE carts (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE cart_items (id BIGINT IDENTITY PRIMARY KEY, cart_id BIGINT NOT NULL, variant_id BIGINT NOT NULL, quantity INT NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (cart_id) REFERENCES carts(id), FOREIGN KEY (variant_id) REFERENCES product_variants(id), UNIQUE(cart_id,variant_id), CHECK(quantity > 0));
CREATE TABLE wishlists (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE wishlist_items (id BIGINT IDENTITY PRIMARY KEY, wishlist_id BIGINT NOT NULL, product_id BIGINT NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY (wishlist_id) REFERENCES wishlists(id), FOREIGN KEY (product_id) REFERENCES products(id), UNIQUE(wishlist_id,product_id));
CREATE TABLE coupons (id BIGINT IDENTITY PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, discount_type VARCHAR(20) NOT NULL, discount_value DECIMAL(19,2) NOT NULL, minimum_order DECIMAL(19,2) NOT NULL DEFAULT 0, maximum_discount DECIMAL(19,2), usage_limit INT, usage_limit_per_user INT, start_at DATETIME2, end_at DATETIME2, status BIT NOT NULL DEFAULT 1, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, CHECK(discount_value >= 0 AND minimum_order >= 0 AND (maximum_discount IS NULL OR maximum_discount >= 0)));
CREATE TABLE orders (id BIGINT IDENTITY PRIMARY KEY, order_code VARCHAR(50) NOT NULL UNIQUE, user_id BIGINT NOT NULL, coupon_id BIGINT, subtotal DECIMAL(19,2) NOT NULL, discount_amount DECIMAL(19,2) NOT NULL, shipping_fee DECIMAL(19,2) NOT NULL, total_amount DECIMAL(19,2) NOT NULL, payment_method VARCHAR(20) NOT NULL, payment_status VARCHAR(20) NOT NULL, order_status VARCHAR(20) NOT NULL, customer_note VARCHAR(1000), cancellation_reason VARCHAR(1000), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(coupon_id) REFERENCES coupons(id));
CREATE TABLE coupon_usages (id BIGINT IDENTITY PRIMARY KEY, coupon_id BIGINT NOT NULL, user_id BIGINT NOT NULL, order_id BIGINT NOT NULL, discount_amount DECIMAL(19,2) NOT NULL, used_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(coupon_id) REFERENCES coupons(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_addresses (id BIGINT IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, receiver_name VARCHAR(150) NOT NULL, receiver_phone VARCHAR(30) NOT NULL, province VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, ward VARCHAR(100) NOT NULL, address_detail VARCHAR(255) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_items (id BIGINT IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, variant_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, sku VARCHAR(80) NOT NULL, size_name VARCHAR(20) NOT NULL, color_name VARCHAR(50) NOT NULL, unit_price DECIMAL(19,2) NOT NULL, quantity INT NOT NULL, total_price DECIMAL(19,2) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id), CHECK(quantity > 0));
CREATE TABLE order_status_history (id BIGINT IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, old_status VARCHAR(20), new_status VARCHAR(20) NOT NULL, changed_by BIGINT, note VARCHAR(1000), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE payments (id BIGINT IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, payment_method VARCHAR(20) NOT NULL, transaction_code VARCHAR(120), amount DECIMAL(19,2) NOT NULL, payment_status VARCHAR(20) NOT NULL, paid_at DATETIME2, response_data NVARCHAR(MAX), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE reviews (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, order_item_id BIGINT NOT NULL UNIQUE, rating INT NOT NULL, comment VARCHAR(2000), status VARCHAR(20) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(order_item_id) REFERENCES order_items(id), CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE banners (id BIGINT IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL, image_url VARCHAR(500) NOT NULL, target_url VARCHAR(500), position VARCHAR(50), start_at DATETIME2, end_at DATETIME2, status VARCHAR(20) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2);
CREATE TABLE notifications (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, content NVARCHAR(MAX) NOT NULL, notification_type VARCHAR(20) NOT NULL, reference_id BIGINT, is_read BIT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE ai_conversations (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(255), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE ai_messages (id BIGINT IDENTITY PRIMARY KEY, conversation_id BIGINT NOT NULL, sender VARCHAR(10) NOT NULL, content NVARCHAR(MAX) NOT NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id));
CREATE TABLE audit_logs (id BIGINT IDENTITY PRIMARY KEY, user_id BIGINT, action VARCHAR(20) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id BIGINT, old_data NVARCHAR(MAX), new_data NVARCHAR(MAX), ip_address VARCHAR(45), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), updated_at DATETIME2, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX idx_orders_user ON orders(user_id); CREATE INDEX idx_orders_status ON orders(order_status); CREATE INDEX idx_orders_created ON orders(created_at); CREATE INDEX idx_payments_transaction ON payments(transaction_code); CREATE INDEX idx_reviews_product ON reviews(product_id); CREATE INDEX idx_notifications_user ON notifications(user_id);
